import numpy as np
# encode demo1 object 1 output coords
one={(4,5),(4,6),(4,7),(4,9),(4,10),(4,11),(5,4),(5,5),(5,11),(5,12),(6,5),(6,11),(7,5),(7,7),(7,8),(7,9),(7,11),(8,5),(8,6),(8,7),(8,9),(8,10),(8,11),(9,6),(9,9)}
# test axes and mismatches
for axis in ['v','h','d','a']:
 best=None
 for k2 in range(0,50):
  def refl(p):
   r,c=p
   if axis=='v': return (r,k2-c)
   if axis=='h': return (k2-r,c)
   if axis=='d': return (c-k2,r+k2) # wrong params
   if axis=='a': return (-c+k2,-r+k2)
  mism=sum(refl(p) not in one for p in one)
  if best is None or mism<best[0]:best=(mism,k2)
 print(axis,best)

# find minimal mismatches for rotations of one
for deg in [90,180]:
 best=(999,None)
 # rotate around centers half grid represented affine formulas brute use transformed centered k
 for a in range(-10,30):
  for b in range(-10,30):
   if deg==180: fn=lambda r,c,a=a,b=b:(a-r,b-c)
   else: fn=lambda r,c,a=a,b=b:(a+c,b-r)
   m=sum(fn(r,c) not in one for r,c in one)
   if m<best[0]:best=(m,(a,b))
 print(deg,best)
